## ISSUES
# list processing issues here so that an editor can look at them


carob_script <- function(path) {

"
Dataset for: COVID-19 and agricultural value chains: Impacts and adaptation of value chain actors in Bangladesh, 2021

Potatoes play an important role in rural livelihoods in Bangladesh. The study is a quantitative assessment to better understand the effects of the COVID-19 pandemic on potato production, post-harvest and marketing, using data from 5 potato value chain actors. 700 potato farmers, 120 potato traders, 52 cold storage owners, 7 seed producers, and 2 potato processors were interviewed between July and November 2021. The information collected was divided into eight sections: A) Introduction, socioeconomic information of respondent, and business basic information (13 questions), (B) Reason for stopping business operations (15 questions), (C) Crop mix and scale of operations (Farmers) / Operations (Other Value Chain actors) (15 questions), (D) Labour use (13 questions for farmers, 8 questions for the rest of the actors), (E) Purchase of inputs and credit for farmers (20 questions) / Procurement for the rest of the actors (24 questions), (F) Sales and marketing (14 questions for farmers and Cold storage owners / 9 questions for the rest of the value chain actors), (G) Overall welfare (15 questions), (H) Adaptation strategies (2 questions).
"

## when done, remove all the default comments, such as this one, from the script
## only keep the comments you added that are specific to this dataset

	uri <- "doi:10.21223/OBJFRB"
	group <- "survey"
	ff  <- carobiner::get_data(uri, path, group)


	meta <- carobiner::get_metadata(uri, path, group, major=1, minor=0,
		# include the data provider and/or all institutes listed as authors (if any)
		data_organization = "CIP; Bangladesh Agricultural University, Mymensingh",
		publication = "",
		project = NA,
		# if available report the experimental or survey design
		design = "unitOfAnalysis: Potato value chain actors; universe: Potato value chain actors from Dhaka, Rangpur, Kulhna, and Rajshahi Divisions; timeMethod: Cross-sectional; dataCollector: International Potato Center; samplingProcedure: Sampling procedures were different for the different value chain actors. For farmers, a list of most important potato districts were selected which resulted in 8 districts (Dinajpur, Rangpur, Bogura, Munshiganj, Jashore, Khulna, Satkhira, Nilphamari) which were weighted again according to the importance of potato production. Households were selected from existing farmer lists where possible. For cold storage owners, list of cold storage owners were created in 5 locations (Dinajpur, Rangpur, Bogura, Munshiganj, Other) from which a random selection was taken. For traders, lists of traders in 5 districts were established (Bogura, Rangpur, Dinajpur, Monshiganj, Jayhatpur) from which an equal number of traders per districts were randomly selected. For seed producers, a list of all potato seed producers was created from which a purposive selection (most important seed producers) and a random selection (small and medium-size seed producers) were taken. For processors, a complete list was created from which we purposively selected the largest ones and randomly selected some small and medium-sized processors.; collectionMode: Data collection was done using standardized questionnaires slightly adapted for different value chain actors and administered in a short 30min phone survey. For this purpose, 5 enumerators were trained and data collection took place between July and November 2021.; researchInstrument: Structured household survey questionnaire",
		
		# data_type can be e.g. "on-farm experiment", "survey", "compilation"
		data_type = NA,
		
		# treatment_vars has semi-colon separated variable names that represent the
		# treatments if the data is from an experiment. E.g. "N_fertilizer;P_fertilizer;K_fertilizer"
		treatment_vars = "",
		
		# response variables of interest such as yield, fwy_residue, disease incidence, etc. Do not include variables
		# that describe management for all treatments or other observations that were not related to the aim of 
		# the trial (e.g. the presence of a disease).
		response_vars = "", 

		# notes for the end-user
		notes = "",

		carob_contributor = "Your Name",
		carob_date = "2026-10-30",
		# The percentage of relevant variables that have been standardized (between 0 and 100%) 
		carob_completion = 0,	
		# The number of hours spent creating this script
		carob_effort = -1
	)
	

	f1 <- ff[basename(ff) == "01_Farmer_Database_Bangladesh_Potato_COVID_ValueChain_2021.xlsx"]
	f2 <- ff[basename(ff) == "02_Cold_Storege_Database_Bangladesh_Potato_COVID_ValueChain_2021.xlsx"]
	f3 <- ff[basename(ff) == "03_Processors_Database_Bangladesh_Potato_COVID_ValueChain_2021.xlsx"]
	f4 <- ff[basename(ff) == "04_Seed_Producer_Database_Bangladesh_Potato_COVID_ValueChain_2021.xlsx"]
	f5 <- ff[basename(ff) == "05_Trader_Database_Bangladesh_Potato_COVID_ValueChain_2021.xlsx"]
	f6 <- ff[basename(ff) == "06_Datadictionary_Bangladesh_Potato_COVID_ValueChain_2021.xlsx"]
	f7 <- ff[basename(ff) == "07_QUESTIONNAIRE- Bangladesh COVID Potato.xlsx"]
	f8 <- ff[basename(ff) == "09_CODEBOOK- Bangladesh Potato COVID.xlsx"]

	r1 <- carobiner::read.excel(f1)
	r2 <- carobiner::read.excel(f2)
	r3 <- carobiner::read.excel(f3)
	r4 <- carobiner::read.excel(f4)
	r5 <- carobiner::read.excel(f5)
	r6a <- carobiner::read.excel(f6, sheet="Farmer")
	r6b <- carobiner::read.excel(f6, sheet="Cold_Storage")
	r6c <- carobiner::read.excel(f6, sheet="Processors")
	r6d <- carobiner::read.excel(f6, sheet="Seed_Producer")
	r6e <- carobiner::read.excel(f6, sheet="Trader")
